#include "canvas/input/input_router.hpp"
namespace canvas::input { DispatchDisposition InputRouter::dispatch(const PointerSampleBatch& batch) { if(batch.terminalCancel) return DispatchDisposition::kCancelled; std::uint64_t previous=lastConfirmed_; for(const auto& sample:batch.samples){ if(sample.sequence==0 || sample.timestampNs==0) return DispatchDisposition::kRejected; if(!sample.predicted){ if(sample.sequence<=previous) return DispatchDisposition::kRejected; lastConfirmed_=sample.sequence; previous=sample.sequence; ++confirmed_; } else ++predicted_; } return DispatchDisposition::kDelivered; } }
